/*
     *  Add a step to the queue for later consideration
     */
void addStep(final int fieldIndex, final NameState nameState, final Set<SubRuleContext> candidateSubRuleIds, final ArrayMembership membershipSoFar) {
    stepQueue.add(new ACStep(fieldIndex, nameState, candidateSubRuleIds, membershipSoFar));
}
